-- GENERATED by tools\Make-UpdateNotes.ps1 from README.md - do not edit by hand.
-- What each pfUI Octo version brought: { version, { { title, text }, ... } }, newest first.
-- updatenotify.lua shows them in the update window and sends the titles to older versions.
pfUI.octoNotes = {
  { "1.1.98", {
    { "Your monitor's Hz", "pick your refresh rate (only the ones your screen offers), vsync and triple buffering in Settings > Performance. Many games stay at 60 Hz on a faster screen until this is set. Apply restarts the graphics for a second and puts everything back by itself in 15 s unless you keep it." },
    { "Frame cap", "1.12 has no frame cap of its own, so the page copies the DXVK line for you: a Steam / Lutris launch option, or one line for dxvk.conf. G-Sync / FreeSync screens get a cap 3 under the Hz." },
    { "Playing on Linux", "one switch for Wine / Proton / Lutris players: no forced wait for the graphics card (more frames), a smooth hardware mouse pointer, lighter effects in dungeons too and the memory ceiling on. Your own settings come back when you switch it off. It also shows which DLLs really loaded." },
    { "Fewer far-away players (PerfBoost)", "with the PerfBoost DLL, set how far players, pets and trash are drawn, in and out of combat. Three ready looks, and PvP-flagged or raid-marked players can always stay drawn. The biggest FPS gain in raids and cities." },
  } },
  { "1.1.97", {
    { "Raid chat window", "opens by itself when you join a raid and shows only what matters in a fight: raid chat and raid warnings, with the leader's and assists' calls standing out and the \"+\" answers gathered under each call as one line of names." },
    { "Taunts and overaggro", "who taunted what (SuperWoW), resisted / missed / dodged / parried taunts in red, and a red OVERAGGRO line when a boss turns to someone who isn't tanking it." },
    { "Healer mana after a fight", "every healer's mana, lowest first, with the raid average." },
    { "Loot", "the master looter's links tagged [ML] and epic loot the raid receives. Links and names click as in any chat, and a box at the bottom talks to the raid." },
    { "Quiet chat in raids", "no General / Trade / LFG / World in your other chat windows while you raid, back the moment you leave or click Q. Chat & Panels > Raid chat, /raidchat test to try it." },
  } },
  { "1.1.96", {
    { "The demo uses your whole action bar", "every spell, item and macro on your bars gets used in turn with its own cooldown sweep, every slot shows the global cooldown, and your trinkets go on cooldown too." },
    { "Resses like a real raid", "after a wipe nobody stands up at once. Ressers get up first, each res has its cast bar and the res icon shows on the one being ressed, and the next pull waits until everyone is up." },
    { "The boss turns for real", "after an overthreat (yours or a raider's), target of target shows whoever has aggro, and the boss hits them until the tank taunts it back." },
    { "A live threat meter all demo long", "a threat cycle runs on its own (a DoT player's countdown, your overthreat, a melee pull), and the meter keeps the last fight between pulls." },
    { "Meter windows never stay stuck small", "a window saved while fitted to its lines grows back to show everyone." },
  } },
  { "1.1.95", {
    { "Smooth bars in every meter", "with ClassicAPI the bars glide to their new size in the game client itself. It's smoother and costs the add-on nothing. A bar that changes player jumps at once." },
    { "Neat columns everywhere", "per second, total and % in columns of their own that line up down every window, with small headings. A narrow window drops columns before it squashes names." },
    { "Windows fit their lines", "no empty space under the last bar." },
    { "Clearer threat window", "the DoTs line names whose DoTs pull next (\"DoTs Gul'dan in 7 s\"), the title shows your own %, \"You hold aggro\" while you tank, calm top lines with their own colour options, and a preview that always matches your meter." },
  } },
  { "1.1.94", {
    { "Threat is back inside Meters", "a big \"Damage, healing & more | Threat\" switch at the top of every Meters page, and a working preview of your threat window." },
    { "% of the pull point", "each player's % is of where THEY pull aggro (110% of the tank in melee, 130% at range). The one the boss is on is first, on \"Aggro\". Nobody else ever reaches 100% until the boss turns to them." },
    { "Everyone's DoT countdown", "every player's line shows their own seconds before they pull, and a \"Next\" line names who pulls next, so a raid leader sees it too. Your own \"DoTs +22.5k\" line shows what your DoTs still add." },
    { "Clear and readable", "info lines in their own colours (DoTs purple, next amber), words that shrink to fit, and the target's full name, never cut." },
    { "Whispers", "a green +N on the bar for new messages, and unfolding goes to the oldest new one first." },
    { "Power dots everywhere", "every section with an on/off dot keeps it while its module is off, so you can always switch it back on." },
  } },
  { "1.1.93", {
    { "OctoThreat, its own section", "your threat window with a live preview, locked to threat so its menu can't switch it away, plus every threat setting on two pages (Threat window / Label & warnings)." },
    { "\"DoTs pull in 4 s\" in the threat window", "the pull line turns red with the countdown, and your line shows the threat still on its way as a lighter part." },
    { "Steadier raid threat", "between the server's answers nobody jumps above the tank on a guess. Only the server's own numbers can put someone past the tank." },
    { "Demo events", "an Events menu on the demo bar and buttons on the Demo mode page: Overthreat, DoTs pull aggro, Tank dies, Raid-wide damage, Big cast, Debuffs to cure, Enrage, Healers out of mana, Someone dies, Battle res, Res everyone, Wipe, Kill the boss." },
    { "Whispers in one window", "a tab per person instead of a window each." },
  } },
  { "1.1.92", {
    { "Demo mode never gets stuck", "if a demo can't start, everything is put back at once and chat says why. Stop always finishes, so you can start again without a reload. Before, a demo that failed to start could leave Stop doing nothing until you reloaded." },
  } },
  { "1.1.91", {
    { "Threat on the way, for warlocks and every DoT class", "the threat label shows where your DoTs and the spell you are casting will take you (\"72% > 88%\"), like incoming heals on a health bar." },
    { "\"DoTs pull in 4 s\"", "a countdown before you pull aggro. \"DoTs pull\" means the DoTs already ticking will do it even if you stop now, so move to the tank. \"Aggro in\" means your current pace gets you there." },
    { "A popup before you pull", "\"DOTS PULL AGGRO IN 3 s\" with the threat sound, and the threat window's pull line shows the countdown too. Settings on Meters > Threat > What is on the way." },
  } },
  { "1.1.90", {
    { "Right-click to attach works with other add-ons", "with the mailbox open, right-clicking an item in your bags adds it to the Send list and opens the Send tab, even when another add-on (like _LazyPig) changes what a bag click does." },
    { "Read every auction is lighter", "a full read only notes prices, no longer redraws the list after every page and takes a short pause between pages, so the game stays smooth on a busy auction house." },
    { "Nameplate spell icons can be turned off", "text on nameplates has its own Spell icon setting (Combat Text > Nameplates > Look). The scroll areas' setting never reached it." },
    { "Quest pins stay inside a round minimap", "pfQuest's pins follow the map's shape (round, diamond, octagon...) instead of spilling over the edge." },
  } },
  { "1.1.89", {
    { "Demos play your own class", "every demo but AFK casts your class's real spells, DoTs, cooldowns and procs, so your action bars, OctoDoTs, cooldown bars, combat text and meters show what you would really see. The Demo Mode page lists the spells it uses." },
    { "Party frames always join in", "if your settings hide the party frames (hidden in raids, raid frames for groups, placed off screen), the demo shows them anyway and says once in chat why they were hidden." },
    { "Every module plays its own test", "cooldown bars, OctoTotems, consumables and the rest cycle through their samples while a demo runs, and the AFK demo has its own AFK screen." },
    { "Crash fix", "a disconnect while a demo was running could crash the game (#132). The demo now cleans up when you leave the world, before the game frees its unit data." },
  } },
  { "1.1.88", {
    { "Every demo is in", "Demo Mode now has its own highlighted row in the sidebar (under More, above Add-ons) and tiles on the Quality of Life page. Six demos, each looping until you press Stop:" },
    { "Nothing a demo does reaches anyone: no raid messages or threat requ...", "Nothing a demo does reaches anyone: no raid messages or threat requests are sent while you are not really in a group." },
  } },
  { "1.1.87", {
    { "Demo mode (raid)", "Quality of Life > Demo mode, or /demo. A pretend 40-player raid on your own frames with all your settings: raid and party frames, a boss on your target frame with its crest, cast bar and abilities, debuffs to cure, raid warnings, meters and combat text. It loops trash, boss, kill or wipe and rest until you stop it. The bar at the top has Pause, speed (0.5x-4x), Next, Edit and Stop. Nothing real happens and Stop puts everything back; a real fight stops it. Needs a full client restart (new files). Dungeon, target dummy, PvP, AFK and showcase demos come next." },
  } },
  { "1.1.86", {
    { "Unit Frames options sorted like ElvUI / EllesmereUI", "the tabs are now the parts of the frame, in order - Frame, Health, Power, Text, Portrait, Buffs & debuffs, Icons & art, Raid layout - and everything every frame shares sits on one gold All frames tab at the end. Names are written in full." },
    { "Change together", "tick Player, Target, Focus (or any frame) under the tabs and every change you make goes to them too. Not their position; it stops when you log out." },
    { "Every dragon and crest as pictures", "Icons & art > Elite, rare and boss art shows every badge as a tile - off, the word, four dragons (Elite Overlay plus three of the game's own) and every crest. Each frame can have its own." },
  } },
  { "1.1.85", {
    { "Faded parts in the unit frame preview", "the elite badge, raid mark, leader, loot and PvP icons now show faded on the Unit Frames preview while they are switched off. Click one to go straight to the setting that turns it on - the faded crest takes you to the Elite Overlay dragons." },
  } },
  { "1.1.84", {
    { "Elite Overlay dragons", "Shagu's pfUI-eliteoverlay is built in. Pick \"Dragons (Elite Overlay)\" under Unit Frames > Frames > Class and status: gold dragons wrap elites and rare elites, red ones world bosses, grey ones rares, on the side \"Badge at\" picks. Needs a full client restart for the new pictures." },
  } },
  { "1.1.83", {
    { "No more game heal numbers over heads", "SuperWoW's own heal numbers could come back on after a client start and float over every player you healed. While pfUI Octo's combat text is on they are now kept off at every login (unless you switched them on yourself on the Combat Text page)." },
    { "Meter windows move on their own", "windows snapped side by side no longer drag each other along. \"Snapped windows move together\" is off by default (Meters > Data) - snapping into line on drop stays." },
  } },
  { "1.1.82", {
    { "Right names on the map", "hovering a party or raid member's dot on the world map could show a player from a group you were in before - the name was read once and kept. It is now read fresh on every hover." },
  } },
  { "1.1.81", {
    { "Moved frames stay put", "a game window you picked with Move anything (the quest log, for example) went back to the game's own place whenever the game laid its windows out. Its saved place now goes back on after that, as it opens, and once more a moment later." },
  } },
  { "1.1.80", {
    { "Whisper windows really open now", "a new window was never given a place on the screen (the game counts a new window as already shown), so nothing appeared - /whispers test included. Each window now starts hidden, gets its place, then shows." },
  } },
  { "1.1.79", {
    { "Whisper windows fixed", "the window per person broke for anyone you had whispered before - its saved conversation went in before the window had a font, which the game refuses. Each window now gets its font the moment it is made." },
  } },
  { "1.1.78", {
    { "ItemRack button shows what you wear", "the set button and the minimap button show a set's picture only while that set is worn exactly. Swap a piece by hand (or wear no set) and they show your worn gear instead, updated every time your gear changes." },
  } },
  { "1.1.77", {
    { "Old ClassicAPI? You'll be told", "OctoLauncher installs an older ClassicAPI (v1.15) with no damage meter. If that's yours, you get one chat line per character on how to get the newest: close the game, run Install pfUI Octo DLLs.bat in your pfUI folder (or the Octo DLL Installer), then start from OctoLauncher - it keeps your new ClassicAPI and doesn't swap it back." },
  } },
  { "1.1.76", {
    { "Pick your meter", "the top of /pfui Meters now has pfUI Octo / ClassicAPI / Blizzard. \"ClassicAPI\" (with ClassicAPI 1.22 or newer) puts our windows away and shows ClassicAPI's own damage meter - and the Windows page becomes its page: style, numbers, when it shows, bar height, gap, text size, class colours, pictures, opacity, with a live preview, plus unlock, new window and reset." },
    { "New hover panel on meter bars", "each spell with its picture and a bar in the player's class colour, then total, per second and share - no other add-ons' tooltip lines mixed in." },
    { "ClassicAPI's numbers in our windows are now opt-in", "(Meters Data), after a crash on one PC when ClassicAPI's meter window loaded. You get one chat line about the new choice the first time you log in with ClassicAPI 1.22. New file: restart the game fully once." },
  } },
  { "1.1.75", {
    { "Totem order", "OctoTotems > Bars > Layout has an Element order choice, so the bars can go Air, Water, Fire, Earth (or any order you like)." },
    { "Earthen Bulwark bar fixed", "it said 0% with a full bulwark. It now reads the integrity from the aura's stack count and from your debuffs too. /bulwark debug prints what the game reports, if it still looks wrong." },
  } },
  { "1.1.74", {
    { "OctoTotems error fixed", "the shield / weapon imbue reminder button had no font for its timer, so \"octototems.lua:952: Font not set\" repeated over and over. Every totem button now gets its font when it is made." },
    { "Website download fixed", "the Download ZIP button works again (the newest releases had the zip under another name)." },
  } },
  { "1.1.73", {
    { "Leftovers go up fast", "after you post full stacks, the Sell tab reads your bags again and puts what's left into the stack size (36 Bronze Bars, one stack of 20 posted, and it's ready to post the 16 left), like aux does. If smaller stacks still fit, it just lowers the number of stacks. The \"in your bags\" count now stays right after a post too." },
  } },
  { "1.1.72", {
    { "Sell tab, quicker", "a 1 by 1 button lists every item on its own (stack size 1, as many as you have). Full stacks uses the biggest stack the item makes. Sliders under Stack size and Number of stacks let you drag or wheel the numbers, and the stacks slider only goes as far as your bags allow." },
    { "Spam Buyout", "keep clicking Buyout and it buys the picked auction and moves to the next one down. A click while the last buy is still going through now waits its turn instead of being refused, and the pick never jumps back to the one being bought." },
  } },
  { "1.1.71", {
    { "Profile import no longer goes dead", "The Import button stays clickable, and a line above it says why a string can't go in yet. If the string is cut short (Discord splits long messages), it tells you to copy all of it or send it as a file. A string pasted with Discord's code block around it now imports too." },
    { "Profile strings read and write better", "A setting with a line break in it used to break the whole string, and now it comes through. One odd line is left out instead of refusing everything. Lists (totem sets, consumables lists, roll rules) keep their order when you share them." },
  } },
  { "1.1.70", {
    { "OctoTotems set editor", "the preview on the Bars and Sets pages is now a fixed grid, one row per element with every totem as an icon. Click one to put it in the set, click it again to take it out, and right-click to hide it on your bars. Nothing grows or shrinks when you hover. The chips on top pick which set you edit (green = the one your key throws). Reset set empties it so you can pick a new one, and New set, Make active and Throw it sit right under it." },
    { "The line under each page's big title no longer runs under the Find box", "It stops before it, a too-long line is cut with \"...\" (hover it for the whole text), and the longest lines (OctoTotems, OctoDoTs, Auctions) were made shorter so they show whole." },
  } },
  { "1.1.69", {
    { "OctoTotems, our own Call of Elements", "a new section for shamans. Four totem bars (fire, earth, water, air) side by side or each on its own, opening on hover, always or never, in any direction, with your own order and hidden totems. Each button shows its timer, a timer line, the cooldown in red once the totem is gone, a glow for the one that is down, red when you've walked out of its range, and a gold dot for the set's totems. Durations come from this server's own spell data (the 90 s Windfury Totem too)." },
    { "Totem sets", "one key throws the next totem that isn't down (or is out of range, or about to run out). With nampower the whole set is queued on one press. Enemy players switch to their class's set, and a set named after a boss is picked when you target it. Ctrl-click a totem to put it in the set; right-click a bar for sets, throw, recall and options." },
    { "Alerts and reminders", "10 / 5 seconds left, run out, destroyed, out of range, and \"all out of range - recall?\" with a glowing Totemic Recall button. Shield and weapon imbue reminders come with a button that puts them back on. The totem advisor lights Poison Cleansing, Disease Cleansing or Tremor when your group needs it." },
    { "Smart heals", "battle heal and best heal keys heal the most hurt member of your group with the smallest rank that covers it. With SuperWoW it does this without changing your target." },
    { "Earthen Bulwark is now part of OctoTotems", "and sticks under the totem bars at the same width (switch that off to place it anywhere)." },
    { "ClassicAPI", "(real totem slots, early deaths, time left, usable/mana), nampower (whole set in one press) and SuperWoW / UnitXP (range from where each totem was dropped), each with a plain fallback. /totems (and /coe while Call of Elements isn't loaded). New files: restart the game fully once." },
  } },
  { "1.1.68", {
    { "Earthen Bulwark bar for tank shamans", "with Elemental Weapons and Rockbiter, a small movable bar shows how full your earthen bulwark is (the server's own integrity %) and about how much it holds (up to 20% of your max health). It turns bright with an 8 s timer line while it is absorbing, and says x3 while you wear a shield. Unit Frames > Earthen Bulwark or /bulwark. New file: restart the game fully once." },
  } },
  { "1.1.67", {
    { "OctoDoTs: pick what shows", "at the top of the Target bar page, Show = Both, Bars only (no target bar) or Target bar only (the Cursive-style bars stay away and cost nothing; they still show in layout mode so you can move them)." },
  } },
  { "1.1.66", {
    { "Meters use ClassicAPI's new damage meter", "with ClassicAPI 1.22 or newer, the current fight and Overall take damage, DPS, healing, HPS, interrupts, dispels, damage taken, deaths and enemy damage taken straight from the DLL - less work for the game in big raids. Earlier fights, the breakdown, uptime, threat and every other display stay ours. ClassicAPI's own meter window stays hidden unless you want it (Meters > Data). New file: restart the game fully once." },
    { "/pfmetercheck", "(or the button on Meters > Data) prints our totals next to ClassicAPI's for the current fight (/pfmetercheck overall for all fights)." },
    { "Target bar, per spell", "right-click a spell's icon (in the preview or the spell grid) for its own glow, when it glows (running out, always, missing), glow colour, time text, number size and place, and animations when it runs out or is put on." },
    { "Target bar box", "it now has its box in layout mode even while switched off, a tidy fixed width (Look > Room for icons), and its tab sits right after General in OctoDoTs." },
  } },
  { "1.1.65", {
    { "OctoDoTs Target bar", "a movable row of your own DoTs and bleeds on your target (Rake, Rip, Moonfire, Insect Swarm, Faerie Fire...), each as its spell icon with the time left and a shade that drains as it runs out. First tab in OctoDoTs, off until you switch it on." },
    { "Pick by icon", "click a spell's icon to always track it (green, greyed while missing) or ignore it (red). Show all of yours or only the tracked ones; size, gap, direction, warning time and opacity. New file: restart the game fully once." },
  } },
  { "1.1.64", {
    { "Layout mode bar you can read and move", "a solid panel (nothing shows through it any more) with the clicks in a strip that is part of it. Drag an empty spot to put it anywhere; right-click it to send it back to the top." },
    { "Show: All pfUI Game", "with Move anything on, choose whether layout mode shows every box, only pfUI's frames, or only the game's and your picked frames." },
    { "Fixed", "red FadingFrame.lua:22 ... startTime errors in chat after layout mode with Move anything on (the zone name frames' own fade is paused while layout mode is open)." },
  } },
  { "1.1.63", {
    { "Move anything", "a switch in layout mode's top bar gives the game's own frames boxes too - quest tracker, quest timers, battleground score, raid warnings, error text, zone name, item link tooltip, follow text, zone map - with snapping, sizing and hiding. Off by default, so layout mode stays tidy; your places, sizes and opacity stay either way." },
    { "Pick a frame", "point at any frame of any add-on and press Enter (or /moveany <FrameName>) - it gets a box like ours." },
    { "Game windows", "Shift + drag the character window, spellbook, quest log, talents, trainers, vendors and more; they open there from then on." },
    { "Clearer layout mode bar", "grouped controls with headings, tooltips on everything, and the clicks always shown under it. Settings > Move anything has opacity per frame, your picked frames and moved windows. New files: restart the game fully once." },
  } },
  { "1.1.62", {
    { "Important enemy buffs on nameplates without SuperWoW", "buff names now also come from ClassicAPI or the buff's tooltip, so \"Important ones\" (Berserker Rage, Recklessness, Ice Block, Evasion...) works for everyone." },
    { "Your own important buffs", "Nameplates > Auras > Enemy buffs - add any buff you want treated as important (names separated by #)." },
  } },
  { "1.1.61", {
    { "/gear back", "puts the set you wore before this one back on - handy in a macro." },
    { "Set names in any capitals", "/gear equip caster finds \"Caster\"; /gear unequip says what it takes off." },
    { "/gear help", "every gear command, also in the ItemRack page's help box with ItemRack's macro calls (EquipSet, UnequipSet, ToggleSet)." },
    { "Shield comes back", "taking off a set with a two-hander puts your off hand back on too." },
  } },
  { "1.1.60", {
    { "Fixes the \"critical error #132\" crashes", "at login and after a /reload (for example after importing a profile): the game was running out of memory. pfUI and pfQuest hold about 290 MB of Lua memory, and Lua let its garbage pile up to twice that before cleaning - more during fights. Now a memory ceiling keeps it in check: out of a fight garbage may grow 64 MB, in a fight by your fight room, and never past 600 MB (Settings > Performance, both adjustable, on by default)." },
    { "Loading clean-up", "pfQuest's 32 MB of quest data no longer leaves its garbage behind while the game loads. New file: restart the game fully once." },
  } },
  { "1.1.59", {
    { "Smoother gear swaps", "a set swap reads your bags once a frame instead of once for every item it moves." },
    { "Closed bags stay quiet", "a closed bag window no longer redraws every slot (and reads every item's tooltip) each time your bags change - it catches up the moment you open it." },
    { "Lighter buff bars", "buff names are remembered until your buffs change, instead of read again every 0.4 seconds." },
    { "Druid stealth paging", "checked only when your buffs or form change (with ClassicAPI / SuperWoW's stealth check), not every frame." },
  } },
}
